import{_ as e,c as t,o as a,a2 as s}from"./chunks/framework.Dez3CbjC.js";const U=JSON.parse('{"title":"[Q011] 什么是 URL 编码 (URL Encode)","description":"","frontmatter":{},"headers":[],"relativePath":"HTML/11-什么是 URL 编码 (URL Encode).md","filePath":"HTML/11-什么是 URL 编码 (URL Encode).md"}'),i={name:"HTML/11-什么是 URL 编码 (URL Encode).md"},d=s(`<h1 id="q011-什么是-url-编码-url-encode" tabindex="-1">[Q011] 什么是 URL 编码 (URL Encode) <a class="header-anchor" href="#q011-什么是-url-编码-url-encode" aria-label="Permalink to &quot;[Q011] 什么是 URL 编码 (URL Encode)&quot;">​</a></h1><p>URL 编码（URL Encoding），也称为百分号编码（Percent Encoding），是一种将 URL 中的字符转化为可以在网络上安全传输的格式的技术。它特别用于处理 URL 中包含的特殊字符，这些字符可能会导致 URL 无法正确传输或解析。</p><h2 id="_1-为什么需要-url-编码" tabindex="-1">1. <strong>为什么需要 URL 编码</strong> <a class="header-anchor" href="#_1-为什么需要-url-编码" aria-label="Permalink to &quot;1. **为什么需要 URL 编码**&quot;">​</a></h2><p>URL 是一种文本格式，但并非所有的字符都可以安全地出现在 URL 中。特别是一些字符，在 URL 中有特殊含义（如分隔符或控制符），而有些字符是非 ASCII 字符，无法直接在 URL 中传输。URL 编码的作用就是将这些字符转换成可以安全传输的格式。</p><h2 id="_2-url-编码的基本规则" tabindex="-1">2. <strong>URL 编码的基本规则</strong> <a class="header-anchor" href="#_2-url-编码的基本规则" aria-label="Permalink to &quot;2. **URL 编码的基本规则**&quot;">​</a></h2><p>URL 编码的过程实际上是将每个字符转换为它在 UTF-8 编码下的十六进制表示，并前面加上一个百分号 <code>%</code>。</p><ul><li><strong>字母（a-z, A-Z）、数字（0-9）、短横线（-）、下划线（_）、点（.）、和波浪符（~）</strong> 等字符是安全的，不需要编码，直接可以在 URL 中使用。</li><li><strong>其他字符</strong>（包括空格、特殊符号、非 ASCII 字符）则会被转换为 <code>%</code> 后跟着该字符的 ASCII 码（或 Unicode 码点）的十六进制值。</li></ul><h2 id="_3-常见字符和它们的编码" tabindex="-1">3. <strong>常见字符和它们的编码</strong> <a class="header-anchor" href="#_3-常见字符和它们的编码" aria-label="Permalink to &quot;3. **常见字符和它们的编码**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字符</th><th>URL 编码</th><th>说明</th></tr></thead><tbody><tr><td>空格</td><td><code>%20</code></td><td>空格在 URL 中不合法，需要转换</td></tr><tr><td><code>#</code></td><td><code>%23</code></td><td>URL 锚点标识符，不能直接使用</td></tr><tr><td><code>&amp;</code></td><td><code>%26</code></td><td>URL 中的查询字符串分隔符</td></tr><tr><td><code>=</code></td><td><code>%3D</code></td><td>URL 查询字符串的键值对分隔符</td></tr><tr><td><code>?</code></td><td><code>%3F</code></td><td>URL 查询字符串的开始符号</td></tr><tr><td><code>/</code></td><td><code>%2F</code></td><td>URL 路径分隔符</td></tr><tr><td><code>:</code></td><td><code>%3A</code></td><td>URL 协议标识符分隔符</td></tr><tr><td><code>+</code></td><td><code>%2B</code></td><td>URL 中加号字符，通常表示空格</td></tr><tr><td><code>%</code></td><td><code>%25</code></td><td>百分号字符本身的编码</td></tr></tbody></table><h2 id="_4-如何进行-url-编码" tabindex="-1">4. <strong>如何进行 URL 编码</strong> <a class="header-anchor" href="#_4-如何进行-url-编码" aria-label="Permalink to &quot;4. **如何进行 URL 编码**&quot;">​</a></h2><p>以 URL 编码为例，我们希望对一个包含特殊字符的 URL 进行编码：</p><h3 id="原始-url" tabindex="-1">原始 URL： <a class="header-anchor" href="#原始-url" aria-label="Permalink to &quot;原始 URL：&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/search?query=hello world&amp;sort=desc</span></span></code></pre></div><p>在 URL 编码前，URL 包含空格（<code>hello world</code>）、和符号（<code>&amp;</code> 和 <code>=</code>），这些符号都需要被编码。编码后的 URL 为：</p><h3 id="编码后的-url" tabindex="-1">编码后的 URL： <a class="header-anchor" href="#编码后的-url" aria-label="Permalink to &quot;编码后的 URL：&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://example.com/search?query=hello%20world&amp;sort=desc</span></span></code></pre></div><p>在这个例子中：</p><ul><li>空格被编码为 <code>%20</code></li><li><code>&amp;</code> 保持不变，因为它在 URL 查询字符串中具有特定的语法意义，但它需要确保不会与其他参数混淆。</li></ul><h2 id="_5-url-编码的应用场景" tabindex="-1">5. <strong>URL 编码的应用场景</strong> <a class="header-anchor" href="#_5-url-编码的应用场景" aria-label="Permalink to &quot;5. **URL 编码的应用场景**&quot;">​</a></h2><ul><li><strong>HTML 表单提交</strong>：当用户通过表单提交数据时，浏览器通常会对表单数据进行 URL 编码，将非 ASCII 字符、空格等转化为编码格式，确保数据能够正确发送到服务器。</li><li><strong>查询字符串</strong>：在 URL 中传递查询参数时，参数值可能包含特殊字符，这些字符也需要 URL 编码。例如，传递含有空格或其他符号的字符串时，必须进行编码以确保它能够在 URL 中传递。</li><li><strong>API 请求</strong>：一些 Web API 接受 URL 作为请求的一部分，发送这些请求时，参数和数据可能包含需要编码的特殊字符。</li></ul><h2 id="_6-如何解码-url" tabindex="-1">6. <strong>如何解码 URL</strong> <a class="header-anchor" href="#_6-如何解码-url" aria-label="Permalink to &quot;6. **如何解码 URL**&quot;">​</a></h2><p>URL 解码是 URL 编码的逆过程，即将编码后的 URL 中的百分号编码（如 <code>%20</code>）转换回原始字符（如空格）。</p><p>例如：</p><ul><li><code>%20</code> 解码为 <code></code></li><li><code>%3D</code> 解码为 <code>=</code></li></ul><p>许多编程语言提供了内建函数来进行 URL 解码，如 JavaScript 中的 <code>decodeURIComponent</code> 函数，Python 中的 <code>urllib.parse.unquote</code> 函数。</p><h2 id="_7-编程语言中的-url-编码" tabindex="-1">7. <strong>编程语言中的 URL 编码</strong> <a class="header-anchor" href="#_7-编程语言中的-url-编码" aria-label="Permalink to &quot;7. **编程语言中的 URL 编码**&quot;">​</a></h2><p>不同的编程语言通常会提供内置函数来处理 URL 编码和解码：</p><ul><li><p><strong>JavaScript</strong>：</p><ul><li><code>encodeURIComponent()</code> 用于编码一个 URI 组件。</li><li><code>decodeURIComponent()</code> 用于解码 URI 组件。</li></ul><p>示例：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://example.com/search?query=hello world&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> encodedUrl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> encodeURIComponent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(encodedUrl); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 输出编码后的 URL</span></span></code></pre></div></li><li><p><strong>Python</strong>：</p><ul><li><code>urllib.parse.quote()</code> 用于编码 URL。</li><li><code>urllib.parse.unquote()</code> 用于解码 URL。</li></ul><p>示例：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> urllib.parse</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://example.com/search?query=hello world&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">encoded_url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> urllib.parse.quote(url)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(encoded_url)</span></span></code></pre></div></li></ul><h2 id="_8-注意事项" tabindex="-1">8. <strong>注意事项</strong> <a class="header-anchor" href="#_8-注意事项" aria-label="Permalink to &quot;8. **注意事项**&quot;">​</a></h2><ul><li>URL 编码并不能保证 URL 一定有效，只是将字符转换为安全的格式。有效的 URL 还需符合其他规范。</li><li>对于中文等非 ASCII 字符，通常使用 UTF-8 编码后再进行 URL 编码。</li><li>编码过程中，如果字符本身已经是有效的 URL 字符，编码器通常会跳过。</li></ul><p>通过 URL 编码，确保 URL 中所有字符都能正确传输，避免因特殊字符引起的问题。</p>`,31),l=[d];function o(n,r,c,h,p,u){return a(),t("div",null,l)}const R=e(i,[["render",o]]);export{U as __pageData,R as default};
